import { z } from 'zod';

import { IsoDateSchema } from '@/data/schemas';

/**
 * The manager's inbox: news generated by the game (offers, deals, contract
 * warnings). Pure and immutable like the rest of `src/game`; saved with the
 * career. Only the newest MAX_MESSAGES are kept so saves stay small.
 */

export const MESSAGE_CATEGORIES = ['offer', 'transfer', 'contract', 'squad'] as const;
export type MessageCategory = (typeof MESSAGE_CATEGORIES)[number];

export const InboxMessageSchema = z.strictObject({
  id: z.string().regex(/^msg_\d+$/),
  date: IsoDateSchema,
  category: z.enum(MESSAGE_CATEGORIES),
  /** Who it's from, e.g. "Chief Scout", "Kestrel Bay". */
  from: z.string().min(1),
  title: z.string().min(1),
  body: z.string(),
  read: z.boolean(),
  /** Offer messages link to the offer so it can be answered from the inbox. */
  offerId: z.string().optional(),
});

export type InboxMessage = z.infer<typeof InboxMessageSchema>;
export type NewMessage = Omit<InboxMessage, 'id' | 'read'>;

export const MAX_MESSAGES = 60;

/** Adds messages (newest first), giving each a fresh sequential id. */
export function addMessages(inbox: readonly InboxMessage[], messages: readonly NewMessage[]): InboxMessage[] {
  if (messages.length === 0) return [...inbox];
  let next = Math.max(0, ...inbox.map((m) => Number(m.id.slice(4)))) + 1;
  const created = messages.map((m) => ({ ...m, id: `msg_${next++}`, read: false }));
  return [...created.reverse(), ...inbox].slice(0, MAX_MESSAGES);
}

export function markRead(inbox: readonly InboxMessage[], id: string): InboxMessage[] {
  return inbox.map((m) => (m.id === id && !m.read ? { ...m, read: true } : m));
}

export function markAllRead(inbox: readonly InboxMessage[]): InboxMessage[] {
  return inbox.map((m) => (m.read ? m : { ...m, read: true }));
}

export const unreadCount = (inbox: readonly InboxMessage[]) => inbox.filter((m) => !m.read).length;
